const tocRows=chapters.filter(c=>c.id!=='12').map(c=>`<a class="toc-row" href="#chapter-${c.id}"><span class="toc-no">${c.id}</span><span>${esc(c.title)}<small>${esc(c.desc)}</small></span><b data-toc="${c.id}">—</b></a>`).join('');
const tocExtras=[...appendix.map(a=>({id:a.id,title:a.title})),{id:'E',title:'15 份可编辑模板与填写示例'},{id:'12',title:'官方来源与核验边界'}].map(a=>`<a class="toc-row compact" href="#${a.id==='12'?'chapter':'appendix'}-${a.id}"><span class="toc-no">${a.id==='12'?'F':a.id}</span><span>${esc(a.title)}</span><b data-toc="${a.id}">—</b></a>`).join('');
function contentHTML(file){let h=file.endsWith('.csv')?csvHTML(file):markdown(file,{pdf:true});return h.replace(/src="([^"\s]+)"/g,(all,src)=>{if(/^(https?:|data:|file:)/.test(src))return all;return `src="file://${path.resolve(ROOT,path.dirname(file),src)}"`;}).replace(/<table>/g,'<table class="print-table">');}
